import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const n="/assets/267_b7ecfad8-2c75-4fa1-b348-86cfee57d9b6.CtZw_c--.png",u=JSON.parse('{"title":"物理服务器网络监控","description":"","frontmatter":{"title":"物理服务器网络监控"},"headers":[],"relativePath":"ops-knowledge-base/dedicated-server/network-monitoring.md","filePath":"ops-knowledge-base/dedicated-server/network-monitoring.md","lastUpdated":1788259091000}'),i={name:"ops-knowledge-base/dedicated-server/network-monitoring.md"};function s(l,t,d,c,h,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h2 id="一、功能概述" tabindex="-1">一、功能概述 <a class="header-anchor" href="#一、功能概述" aria-label="Permalink to &quot;一、功能概述&quot;">​</a></h2><p>网络监控功能为用户提供了服务器网络流量的可视化监控能力。通过直观的流量图，用户可以清晰了解服务器在不同时间段内的网络流入、流出等流量情况，助力用户及时掌握网络状态，为服务器的网络资源规划、故障排查等提供数据支持。</p><h2 id="二、功能入口" tabindex="-1">二、功能入口 <a class="header-anchor" href="#二、功能入口" aria-label="Permalink to &quot;二、功能入口&quot;">​</a></h2><p>登录平台，进入客户中心，下方**“我的订单”** 点击 <strong>“物理服务器”</strong>。或者在 <strong>“产品管理”</strong> 点击 <strong>“物理服务器”</strong>，根据机器所在地区和状态筛选。<strong>在页面上方标签栏中点击</strong>“网络监控”**，即可进入网络监控界面。</p><p><img src="'+n+'" alt=""></p><h2 id="三、界面与功能说明" tabindex="-1">三、界面与功能说明 <a class="header-anchor" href="#三、界面与功能说明" aria-label="Permalink to &quot;三、界面与功能说明&quot;">​</a></h2><h3 id="一-流量图区域" tabindex="-1">（一）流量图区域 <a class="header-anchor" href="#一-流量图区域" aria-label="Permalink to &quot;（一）流量图区域&quot;">​</a></h3><ol><li><p><strong>时间范围选择</strong>：在流量图上方，提供 “1h”“2h”“3h”“6h”“12h”“1d”“3d”“7d”“14d”“1m”“所有” 等时间范围选项，用户可根据需求选择查看不同时长内的流量情况。同时，也可在右侧自定义时间区间，精准定位特定时间段的流量数据。</p></li><li><p><strong>流量趋势展示</strong>：流量图以折线等形式展示网络流量趋势，不同颜色线条代表不同流量类型：</p><ul><li>（Incoming traffic on interface [平均]）：接口平均流入流量。</li><li>（Outgoing traffic on interface [平均]）：接口平均流出流量。</li><li>（Inbound 95th Percentile）：流入流量。</li><li>（Outbound 95th percentile）：流出流量。</li><li>（Inbound + Outbound 95th percentile）：流入与流出流量之和。</li></ul></li></ol><h3 id="二-流量统计信息" tabindex="-1">（二）流量统计信息 <a class="header-anchor" href="#二-流量统计信息" aria-label="Permalink to &quot;（二）流量统计信息&quot;">​</a></h3><p>在流量图下方，展示了流量的<strong>最新</strong>、<strong>平均</strong>、<strong>最大</strong>等统计数据，对应不同流量类型，帮助用户快速了解流量的关键指标情况。</p><h2 id="四、使用价值" tabindex="-1">四、使用价值 <a class="header-anchor" href="#四、使用价值" aria-label="Permalink to &quot;四、使用价值&quot;">​</a></h2><ol><li><strong>网络资源规划</strong>：通过长期的流量监控数据，用户可分析服务器网络流量的规律与峰值，合理规划网络资源，避免因资源不足影响业务运行。</li><li><strong>故障排查</strong>：当服务器网络出现异常（如流量突增或突降）时，可通过网络监控功能快速定位问题时间段和流量异常类型，为故障排查提供方向。</li><li><strong>性能优化</strong>：依据流量监控数据，可对服务器的网络配置、应用部署等进行优化调整，提升网络性能和业务体验。</li></ol>',12)])])}const _=e(i,[["render",s]]);export{u as __pageData,_ as default};
